+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collection;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>The name text is split on whitespace into terms; every term must appear in
+ * the customer's first or last name, ignoring case and accents. With no
+ * statuses given, every status matches.
+ *
+ * @param name     free-text name filter; may be blank
+ * @param statuses statuses to keep; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null || statuses.isEmpty()
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
+        return new CustomerFilter(name, statuses == null ? Set.of() : Set.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return terms().isEmpty() && statuses.isEmpty();
+    }
+
+    /** The normalized name terms; empty when the name filter is blank. */
+    public List<String> terms() {
+        String normalized = normalize(name).strip();
+        return normalized.isEmpty() ? List.of() : Arrays.asList(WHITESPACE.split(normalized));
+    }
+
+    Predicate<Customer> toPredicate() {
+        List<String> terms = terms();
+        Set<CustomerStatus> wanted = statuses;
+        return customer -> {
+            if (!wanted.isEmpty() && !wanted.contains(customer.status())) {
+                return false;
+            }
+            if (terms.isEmpty()) {
+                return true;
+            }
+            String first = normalize(customer.firstName());
+            String last = normalize(customer.lastName());
+            return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+        };
+    }
+
+    /** Folds case and strips accents, so {@code Mäkinen} and {@code MAKINEN} compare equal. */
+    static String normalize(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFKD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
